<?php
/**
 * Critical CSS: the rules that style the first screen are printed inline, and the full
 * stylesheet loads without blocking the first paint.
 *
 * The files in assets/css/critical/ are generated by bin/critical-css.mjs (home, single and archive,
 * plus a -box set for the box design). Turn the
 * feature off with the `wplusui_use_critical_css` filter or by enabling SCRIPT_DEBUG.
 *
 * @package wplus-ui
 */

if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

/**
 * Which critical file fits the current request.
 *
 * @return string home, single or archive.
 */
function wplusui_critical_kind() {
	if ( is_front_page() || is_home() || ( is_search() && wplusui_show_sidebar( 'search' ) ) ) {
		return 'home';
	}
	return is_singular() ? 'single' : 'archive';
}

/**
 * File name (without extension) of the critical CSS for this request: the box design has its own set.
 *
 * @return string
 */
function wplusui_critical_name() {
	return wplusui_critical_kind() . ( wplusui_box_design() ? '-box' : '' );
}

/**
 * Whether critical CSS is used for this request.
 *
 * @return bool
 */
function wplusui_critical_enabled() {
	if ( ( defined( 'SCRIPT_DEBUG' ) && SCRIPT_DEBUG ) || is_customize_preview() || is_admin() ) {
		return false;
	}
	$file = WPLUSUI_DIR . '/assets/css/critical/' . wplusui_critical_name() . '.css';
	return (bool) apply_filters( 'wplusui_use_critical_css', is_readable( $file ) );
}

/**
 * Print the critical CSS first in <head>.
 */
function wplusui_print_critical_css() {
	if ( ! wplusui_critical_enabled() ) {
		return;
	}
	$css = file_get_contents( WPLUSUI_DIR . '/assets/css/critical/' . wplusui_critical_name() . '.css' ); // phpcs:ignore WordPress.WP.AlternativeFunctions.file_get_contents_file_get_contents -- local theme file.
	if ( $css ) {
		echo '<style id="wplusui-critical">' . str_replace( '</style', '<\/style', $css ) . "</style>\n"; // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped -- theme file.
	}
}
add_action( 'wp_head', 'wplusui_print_critical_css', 1 );

/**
 * Load the full stylesheet without blocking rendering.
 *
 * @param string $tag    Link tag.
 * @param string $handle Style handle.
 * @return string
 */
function wplusui_async_main_style( $tag, $handle ) {
	if ( 'wplusui-style' !== $handle || ! wplusui_critical_enabled() ) {
		return $tag;
	}
	$async = str_replace( "rel='stylesheet'", "rel='preload' as='style' onload=\"this.onload=null;this.rel='stylesheet'\"", $tag );
	return $async . '<noscript>' . $tag . '</noscript>' . "\n";
}
add_filter( 'style_loader_tag', 'wplusui_async_main_style', 10, 2 );
